PM=H+[['希腊 phōnéō → phṓnēma → 法语 phonème → 英语 phoneme','发声 → 发出的声音；现代语言学用来表示音位']]
PL=P+[['英语 phono- + -logy → phonology','研究语言怎样组织声音的学科；亦说一门语言的音系']]
SY=H+[['希腊 syn- + phōnḗ → sýmphōnos / symphōnía','共同发声、声音协调'],['拉丁 symphonia／古法语 simphonie → 中古英语 symphony','和谐声音、乐器名称；后来发展为交响曲']]
AN=H+[['希腊 antíphōnos → antíphōna〔中性复数〕→ 拉丁 antiphona','回应的声音 → 应答唱诵']]
EU=H+[['希腊 eu- + phōnḗ → euphōnía → 法语 euphonie → 英语 euphony','好听的声音 → 悦耳、谐音效果']]
HO=H+[['希腊 homós + phōnḗ → homóphōnos / homophōnía','相同的声音；齐声、协调的声音']]
PA=H+[['法语 phonation → 英语 phonation','以希腊“声音”加 -ation 命名发声过程']]
W=[
E('phone','英 /fəʊn/；美 /foʊn/','电话；打电话；音素〔语言学〕','日常是把声音送到远处的工具；语言学里则是一段实际发出来的语音。','电话义缩短自 telephone；音素义另从希腊 phōnḗ“声音”引入，不是把电话借来命名发音。',TEL+[['并列：希腊 phōnḗ → 英语 phone〔语音术语〕','一个实际的语音音段，与电话缩略路线分开']],'answer the phone 是接电话，phone someone 是给人打电话。语言学说 a phone 时，指听到或分析到的音；同一个音位可以有不止一种实际读法。','on the phone；phone someone；a speech phone。','phone〔音素〕重实际声音；phoneme〔音位〕重该声音在某种语言中是否用来区分词。',('I will phone you when the train arrives.','火车到站后我会给你打电话。'),('The two phones are different realizations of the same phoneme.','这两个音素是同一个音位的不同实现。'),sources=['https://www.etymonline.com/word/phone','https://en.wiktionary.org/wiki/phone#English']),
E('microphone','英 /ˈmaɪkrəfəʊn/；美 /ˈmaɪkrəfoʊn/','麦克风；话筒','把空气里的声音接住，转成可以传输、放大或录下的信号。','近代用 micro- “小、微弱” + -phone “声音”构词；早期名称用于听微弱声音的装置，后来用于电声话筒。',P+[['英语 micro- + -phone → microphone','小声音的器具 → 把声音转换为电信号的装置']],'micro- 在名称里不保证实物很小。麦克风负责拾音、转换，扬声器负责把信号变回声音；很多设备把这两个部件装在一起，功能仍不同。','speak into a microphone；a wireless microphone；mute the microphone。','megaphone 是让人声传得更远的扩音器；microphone 首先是收进声音，不必自身发出很响的声。',('Please keep the microphone close enough to pick up your voice.','请把麦克风放近一些，让它能收清你的声音。'),('The microphone recorded every page rustle.','麦克风把每一次翻页的沙沙声都录下来了。'),sources=['https://en.wiktionary.org/wiki/microphone#English','https://www.etymonline.com/word/microphone']),
E('megaphone','英 /ˈmeɡəfəʊn/；美 /ˈmeɡəfoʊn/','扩音器；喊话筒；宣传放大渠道','让一个人的声音变得更响、更有指向，送到更多人那里。','英语 mega- “大” + -phone “声音”；化学同形词 megaphone 另由植物名 Aniba megaphylla 与 -one 命名，不能按扩音器解释。',P+[['英语 mega- + -phone → megaphone','大声音的器具 → 扩音喊话；比喻传播声音的渠道'],['另源同形：植物名 megaphylla + -one → megaphone〔化合物〕','天然产物命名，不走“声音”成分']],'最简单的是喇叭口形的喊话筒，也可以带电子放大。a megaphone for a campaign 比喻替活动扩大声量的平台。mega- 在这里说“大”，不是百万倍的声强。','speak through a megaphone；a handheld megaphone；a megaphone for a cause。','microphone 把声音收进系统；megaphone 把说话声向外送。化合物同名只需认清另源。',('The guide used a megaphone to address the crowd.','向导用扩音器向人群讲话。'),('The festival gave local musicians a megaphone for their work.','音乐节为当地音乐人提供了宣传作品的渠道。'),sources=['https://en.wiktionary.org/wiki/megaphone#English']),
E('phonograph','英 /ˈfəʊnəɡrɑːf/；美 /ˈfoʊnəɡræf/','留声机；唱机；录音装置〔历史用法〕','把声音“写”成可保存的轨迹，再把轨迹读成声音。','近代 phono- “声音” + -graph “书写、记录”；技术名称并非古希腊已有留声机。',P+[['英语 phono- + -graph → phonograph','声音的记录器；后来也指播放这些记录的唱机']],'早期机器把振动刻在圆筒等载体上，针沿着纹路运行便能重现声音。现代美式英语也可用 phonograph 说唱机；这个名称强调记录，不是摄影。','an early phonograph；a phonograph cylinder；a phonograph record。','phonogram 可指录下来的声音或表音符号；phonograph 通常是设备。gramophone 常偏向使用唱片的唱机。',('The museum demonstrated a phonograph that played wax cylinders.','博物馆演示了一台播放蜡筒的留声机。'),('A scratchy voice emerged from the old phonograph.','旧留声机里传出带着沙沙声的人声。'),sources=['https://en.wiktionary.org/wiki/phonograph#English','https://www.etymonline.com/word/phonograph']),
E('telephony','/təˈlefəni/','电话通信；电话技术','不只是一部电话，而是把通话送到另一端的一整套技术与业务。','telephone + -y；telephone 的 tele- 来自希腊“远”，后半来自“声音”。',TEL[:-1]+[['英语 telephone + -y → telephony','电话的传声过程、系统和技术']],'internet telephony 是通过互联网实现语音通信。telephony 着眼于通话系统和服务，不是某个手机品牌，也不限于铜线。重音在第二音节，与 telephone 不同。','mobile telephony；internet telephony；telephony services。','telephone 是设备或打电话；telephony 是通信领域或技术，通常不可数。',('Internet telephony allowed the offices to communicate cheaply.','互联网电话技术让各办公室能低成本通话。'),('The course covers the history of mobile telephony.','课程讲授移动电话通信的发展史。'),sources=['https://en.wiktionary.org/wiki/telephony#English']),
E('telephonic','英 /ˌtelɪˈfɒnɪk/；美 /ˌteləˈfɑːnɪk/','电话的；通过电话进行的','把“这件事是通过电话完成的”放到名词前说明。','telephone + -ic，去掉词尾 e，重音移到 -phon-。',TEL[:-1]+[['英语 telephone + -ic → telephonic','与电话有关的；通过电话传递的']],'telephonic interview 是电话访谈，telephonic communication 是电话通信。这种形容词较正式；日常更常直接说 a phone interview。','telephonic communication；a telephonic interview；telephonic contact。','telephonic 说通信方式；phonetic 说语音性质，不是同一个技术领域。',('The report was based on a telephonic interview.','报告依据一次电话访谈写成。'),('They maintained telephonic contact throughout the journey.','旅途中他们一直保持电话联系。'),sources=['https://en.wiktionary.org/wiki/telephonic#English']),
E('smartphone','英 /ˈsmɑːtfəʊn/；美 /ˈsmɑːrtfoʊn/','智能手机','电话里加入可运行多种程序的计算能力，随身带着一个小型工具箱。','英语 smart“有智能功能的” + phone；phone 是 telephone 的缩略。',TEL+[['英语 smart + phone → smartphone','具有较强计算与应用功能的移动电话']],'它能通话，也能拍照、导航和运行应用。smart 描述设备功能，不表示手机会像人一样理解每件事，更不评价使用者是否聪明。','a smartphone app；use a smartphone；charge a smartphone。','mobile phone 是移动电话的总称；smartphone 强调智能功能，与较简单的 feature phone 对照。',('She used her smartphone to scan the ticket.','她用智能手机扫描了车票。'),('The museum offers an audio guide through a smartphone app.','博物馆通过智能手机应用提供语音导览。'),sources=['https://en.wiktionary.org/wiki/smartphone#English']),
E('headphone','英 /ˈhedfəʊn/；美 /ˈhedfoʊn/','耳机；耳机的〔定语，通常用复数 headphones〕','把小型发声单元戴到头部，让声音直接送到耳边。','英语 head + phone，后半用声音器具的成分；并非“头部电话”这一整句的字面义。',P+[['英语 head + phone → headphone / headphones','戴在头上的声音接收器；通常以一副耳机的复数形式使用']],'日常说 a pair of headphones、put on headphones；单数 headphone 常见于 headphone jack“耳机插孔”等定语。这里的复数通常指一副设备，不是很多副。','a pair of headphones；a headphone socket；wear headphones。','earphones 常更偏小型、贴耳或入耳的耳机；headphones 常偏戴在头上的一副，实际产品名称会有重叠。',('I put on my headphones so the music would not disturb anyone.','我戴上耳机，免得音乐打扰别人。'),('The headphone socket is beside the charging port.','耳机插孔在充电接口旁边。'),sources=['https://en.wiktionary.org/wiki/headphone#English','https://dictionary.cambridge.org/dictionary/english/headphones']),
E('earphone','英 /ˈɪəfəʊn/；美 /ˈɪrfoʊn/','耳机；耳塞式听筒','把传来的信号变成只在耳旁播放的声音。','英语 ear + phone；与 headphone 同属近代声音器具命名。',P+[['英语 ear + phone → earphone','放在耳边或耳中的小型声音接收器']],'可以单指一只听筒，也常用复数 earphones 指一对。插入耳内的 earbud 是常见形式，但 earphone 并不要求所有产品都用同一种外形。','a pair of earphones；wireless earphones；remove an earphone。','microphone 收音，earphone 放音；有通话功能的耳机通常另有麦克风。',('Only the left earphone was working.','只有左边那只耳机能响。'),('She removed one earphone to hear the announcement.','她摘下一只耳机，好听清广播。'),sources=['https://en.wiktionary.org/wiki/earphone#English']),
E('stereophonic','英 /ˌsteriəˈfɒnɪk/；美 /ˌsteriəˈfɑːnɪk/','立体声的','让不同位置的声道共同工作，听起来有左右位置和空间层次。','近代 stereo- “立体、坚实” + -phonic “声音的”，仿 stereoscopic“立体视觉的”构词；并非指声音变成了固体。',P+[['希腊 stereós“坚实的”→ stereo- + -phonic → stereophonic','把空间立体感用于声音重放']],'常见立体声用左右两个声道，让乐器听起来像在不同位置。把同一个单声道信号接到两个扬声器，不会自动得到真正的声道空间差异。','stereophonic sound；a stereophonic recording；stereophonic reproduction。','monophonic 在录音里是单声道；polyphonic 在音乐织体里是多条旋律，不是在数录音声道。',('The stereophonic recording places the violin slightly to the left.','这段立体声录音让小提琴听起来稍微偏左。'),('The engineer compared the original mono mix with a stereophonic version.','工程师比较了原来的单声道混音和立体声版本。'),sources=['https://en.wiktionary.org/wiki/stereophonic#English']),
E('stereo','英 /ˈsteriəʊ/；美 /ˈsterioʊ/','立体声；立体声音响；立体的〔其他缩略路线〕','日常把 stereophonic 的后半截省掉，保留“有空间感的声音”这个意思。','音响义缩短自 stereophonic；摄影的 stereo 也可缩自 stereoscopic，旧印刷义可缩自 stereotype，不是所有 stereo 都藏着 -phone。',P+[['stereo- + -phonic → stereophonic → stereo〔音响〕','立体声的 → 立体声、立体声音响'],['并列缩略：stereoscopic / stereotype → stereo','立体摄影或印刷用语，另走不同完整词']],'listen in stereo 是听立体声；turn on the stereo 是打开音响。摄影里的 stereo pair 则是一对用于产生立体视觉的图像，要靠语境认出缩略前的词。','in stereo；a stereo system；a stereo recording。','stereo 不等于“音量大”或“高音质”。它主要说声音的空间重现方式。',('The album is available in both mono and stereo.','这张专辑有单声道和立体声两个版本。'),('He turned the stereo down before answering the door.','他先调低音响，再去开门。'),sources=['https://en.wiktionary.org/wiki/stereo#English']),
E('saxophone','英 /ˈsæksəfəʊn/；美 /ˈsæksəfoʊn/','萨克斯管','以发明者的姓命名的发声乐器，声音从簧片振动开始。','法语 saxophone：发明者 Adolphe Sax 的姓 + -o- + -phone；Sax 是人名，不是 sex，也不是“六”的词根。',P+[['法语 Sax + -o- + -phone → saxophone → 英语 saxophone','萨克斯发明的声音器具']],'通常有金属管身，却属于木管乐器，因为发声方式是吹动单簧片，不是像小号那样靠嘴唇振动。现代爵士和古典音乐都使用它。','play the saxophone；an alto saxophone；a saxophone solo。','brass 可说黄铜材质，也可说铜管乐器类别；金属外观不自动把萨克斯归进铜管组。',('The saxophone carried the melody above the rhythm section.','萨克斯在节奏组之上吹奏主旋律。'),('She switched from alto to tenor saxophone for the final piece.','最后一首曲子，她从中音萨克斯换成了次中音萨克斯。'),sources=['https://en.wiktionary.org/wiki/saxophone#English']),
E('xylophone','英 /ˈzaɪləfəʊn/；美 /ˈzaɪləfoʊn/','木琴','排列好的木条被敲一下，各自振出不同音高。','近代 xylo- “木” + -phone “声音”；xylo- 来自希腊 xýlon“木材”。',[['希腊 xýlon；phōnḗ', '木材；声音——两种并列的构词材料'], ['近代组合形式 xylo- + -phone', '木 + 声音，用于乐器命名'], ['英语 xylophone', '敲击木条发声的木琴']],'它用长短等性质不同的木条产生不同音高，常以槌击奏。玩具商品有时把金属片乐器也标成 xylophone，严格的乐器分类会把材质分清。','play the xylophone；a wooden xylophone；xylophone mallets。','idiophone 是本体振动发声的大类，xylophone 是其中木条组成的一种；不是所有打击乐器都是木琴。',('The child struck each wooden bar of the xylophone in turn.','孩子依次敲击木琴上的每根木条。'),('A bright xylophone melody cuts through the orchestral texture.','清亮的木琴旋律从管弦乐的层次中显出来。'),sources=['https://en.wiktionary.org/wiki/xylophone#English'])
]
W.extend([
E('phonetic','/fəˈnetɪk/','语音的；按读音表示的','先听它实际上怎么响，再用符号记录，而不是只盯着普通拼写。','借近代拉丁 phoneticus，接希腊 phōnētikós“声音的”；现代可看出 phon-，但不是先有英语 phone 再临时添后缀。',PH,'phonetic transcription 是用音标记录语音；phonetic spelling 是按声音拼写的办法。说两种读法有 phonetic differences，关注的是发音细节，不一定能改变词义。','phonetic symbols；phonetic transcription；phonetic differences。','phonemic 问这种差别在该语言里是否区分词；phonetic 更细地观察声音本身。',('The dictionary gives a phonetic transcription beside each word.','词典在每个单词旁标出音标。'),('The two speakers differ in small phonetic details.','两位说话者的发音在细节上有所不同。'),sources=['https://www.etymonline.com/word/phonetic','https://en.wiktionary.org/wiki/phonetic#English']),
E('phonetics','/fəˈnetɪks/','语音学','研究嘴、舌头、声带怎样发声，声音怎样传播，又怎样被耳朵和大脑听见。','phonetic + 学科词尾 -s / -ics；词尾 s 是学科名的一部分，不表示几门语音学。',PH+[['英语 phonetic + -s → phonetics','关于实际语音的系统研究']],'可以研究舌头位置、声带振动、声学波形和听辨。它不只教“这个单词该怎样读”，也研究人类语音的共同机制与差异。','articulatory phonetics；acoustic phonetics；study phonetics。','phonology 看语言怎样把声音组织成有区别、有规则的系统；phonetics 看声音怎样产生、呈现和被感知，两门学问有交叉。',('In phonetics class, we compared voiced and voiceless sounds.','语音学课上，我们比较了浊音和清音。'),('Acoustic phonetics uses measurements to study recorded speech.','声学语音学通过测量来研究录下的语音。'),sources=['https://en.wiktionary.org/wiki/phonetics#English']),
E('phonetically','/fəˈnetɪkli/','按语音地；从实际发音看','暂时把字母拼写放一边，按耳朵听到的发音来处理。','phonetic + -ally；词尾通常压缩读，不必逐个拼出每个书写音节。',PH+[['英语 phonetic + -ally → phonetically','从语音角度；按实际读音表示']],'write a name phonetically 是按发音记名字。两个词若 phonetically similar，只是声音相近，不保证意思相近或拥有同一词根。','transcribe phonetically；spell phonetically；phonetically similar。','phonemically 常忽略不区分词义的细节；phonetically 可以记录这些细节。',('She wrote my name phonetically so she could pronounce it later.','她按读音记下我的名字，方便以后念出来。'),('The words look different but are phonetically similar.','这些词看起来不同，发音却相似。'),sources=['https://en.wiktionary.org/wiki/phonetically#English']),
E('phonics','英 /ˈfɒnɪks/；美 /ˈfɑːnɪks/','自然拼读；字母与语音对应的教学方法','学着把看到的字母变成声音，再把声音连起来读词。','phon- “声音” + -ics；早期可泛指语音研究，现代常指读写教学方法。',P+[['英语 phon- + -ics → phonics','声音研究 → 通过字母与语音对应学习读写']],'孩子学 sh 常对应 /ʃ/，再把各部分连成词，就是典型 phonics 活动。它教的是拼写与声音的关系，不意味着每个字母只有一种永不变化的读法。','phonics instruction；a phonics lesson；systematic phonics。','phonetics 是研究语音的学科；phonics 是阅读教学方法，两个词不能因只差几个字母就互换。',('The phonics lesson focused on the sound represented by sh.','这节自然拼读课重点学习 sh 所表示的声音。'),('The children used phonics to read an unfamiliar word.','孩子们利用自然拼读读出了一个没见过的词。'),sources=['https://en.wiktionary.org/wiki/phonics#English']),
E('phoneme','英 /ˈfəʊniːm/；美 /ˈfoʊniːm/','音位','语言把某些声音差别当成“换了就可能换一个词”的区别。','希腊 phṓnēma“发出的声音”经法语 phonème 借入；现代的 -eme“单位”用法正是受这类词推动，不能倒写成古希腊先有英语后缀。',PM,'英语 pin 与 bin 的差别让 /p/ 和 /b/ 成为不同音位。一个音位不是固定的一段录音：不同人、不同位置发出来会有变化，仍可能被语言当成同一类。','a vowel phoneme；a consonant phoneme；a contrast between phonemes。','字母是书写单位；phoneme 是语言系统里的语音单位。ship 有四个字母，通常分析为三个音位 /ʃ ɪ p/。',('Changing one phoneme turns pin into bin.','换一个音位，就能把 pin 变成 bin。'),('The word ship contains three phonemes in this analysis.','按这种分析，ship 含三个音位。'),sources=['https://www.etymonline.com/word/phoneme','https://en.wiktionary.org/wiki/phoneme#English']),
E('phonemic','/fəˈniːmɪk/','音位的；能区分词义的','声音有差别还不够，得看这门语言是否用这个差别认出不同的词。','phoneme + -ic，去掉末尾 e；重音落到 -nem-。',PM+[['英语 phoneme + -ic → phonemic','属于音位层次；有区分词义的作用']],'phonemic contrast 是音位对立。英语 pin 与 spin 中 p 的送气差别通常不区分词；别的语言可以把类似差别当作区分词的依据。音位关系要放在某一种语言内判断。','phonemic contrast；phonemic transcription；phonemic awareness。','phonetic difference 是发音不同；phonemic difference 还要求在该语言系统里起区别作用。',('The contrast between /p/ and /b/ is phonemic in English.','/p/ 与 /b/ 的对立在英语中属于音位对立。'),('This phonemic transcription leaves out predictable pronunciation details.','这份音位转写省略了可以预测的发音细节。'),sources=['https://www.etymonline.com/word/phonemic','https://en.wiktionary.org/wiki/phonemic#English']),
E('phonology','英 /fəˈnɒlədʒi/；美 /fəˈnɑːlədʒi/','音系学；一门语言的音系','看一门语言如何把声音排成自己的规则：哪些能区别词，哪些能挨在一起，重音放哪里。','近代 phono- “声音” + -logy “研究”；现代也用于手语中对手形、位置、运动等形式单位的组织研究。',PL,'English phonology 可指英语的音系，也可指对它的研究。讨论哪些辅音能组成词首、复数词尾为何变音，都是这门学问关心的问题。手语音系并不要求手语产生声音。','English phonology；the phonology of a language；segmental phonology。','phonetics 着眼声音实现，phonology 着眼系统组织；手语用法说明现代学科义已超出字面“声音”。',('The course examines stress patterns in English phonology.','课程研究英语音系中的重音模式。'),('The two dialects differ in vocabulary and phonology.','这两种方言在词汇和音系方面都有差别。'),sources=['https://en.wiktionary.org/wiki/phonology#English']),
E('phonological','英 /ˌfɒnəˈlɒdʒɪkəl/；美 /ˌfɑːnəˈlɑːdʒɪkəl/','音系的；音系学的','与声音在语言中的分类、组合和变化规则有关。','phonology + -ical，-logy 改为 -logical；不是说“声音很有逻辑”。',PL+[['英语 phonology → phonological','音系研究及音系规则的形容词']],'phonological rule 可以解释某个声音到了特定环境为什么变形。phonological awareness 是对词里的音节、音韵等结构的意识，范围常比只辨音位的 phonemic awareness 更宽。','phonological rules；phonological awareness；phonological change。','phonological 不等于“拼写的”；同一个拼写形式可能有不同的音系分析。',('The researcher proposed a phonological rule for the alternation.','研究者为这种交替提出了一条音系规则。'),('Rhyming games can draw attention to phonological patterns.','押韵游戏能让人注意语音结构中的规律。'),sources=['https://en.wiktionary.org/wiki/phonological#English']),
E('phonologist','英 /fəˈnɒlədʒɪst/；美 /fəˈnɑːlədʒɪst/','音系学家','专门研究语言怎样组织语音或对应形式单位的人。','phonology 对应的人名形式 -logist；phono- 接希腊声音，-logist 表示研究某领域的人。',PL+[['英语 phonology → phonologist','研究音系系统的专家']],'他可能研究一种语言为什么容许某些音连在一起、为什么重音会移动。phonologist 是研究方向名称，不意味着本人必须能模仿所有口音。','a phonologist；work with a phonologist；a theoretical phonologist。','phoneticist / phonetician 更突出实际语音的产生与感知；phonologist 更突出语言系统，两类研究常合作。',('The phonologist compared stress patterns across three languages.','音系学家比较了三种语言的重音模式。'),('A phonologist helped analyse the sound changes in the dialect.','一位音系学家协助分析了这种方言的语音变化。'),sources=['https://www.merriam-webster.com/dictionary/phonologist','https://en.wiktionary.org/wiki/phonologist#English']),
E('phoneticist','/fəˈnetɪsɪst/','语音学家；语音拼写法的倡导者〔较少见〕','专门观察、分析语音的人；旧语境也可说支持按发音改拼写的人。','phonetic + -ist，构成人的名称；与更常见的 phonetician 同义或近义。',PH+[['英语 phonetic + -ist → phoneticist','语音研究者；按音拼写的支持者']],'现代谈专业研究者通常更常见 phonetician。phoneticist 仍能用于研究语音的人，重点是研究对象而非“发音很标准的人”。','a phoneticist；a trained phoneticist；the work of a phoneticist。','phonologist 主要研究音系系统；phoneticist 主要研究语音实现。两种称呼不是“会说话”与“不会说话”的区别。',('The phoneticist measured how long the vowel lasted.','语音学家测量了这个元音持续的时间。'),('A phoneticist listened to the recording several times before transcribing it.','语音学家把录音听了几遍，才开始转写。'),sources=['https://www.merriam-webster.com/dictionary/phoneticist','https://www.collinsdictionary.com/us/dictionary/english/phoneticist']),
E('allophone','英 /ˈæləfəʊn/；美 /ˈæləfoʊn/','音位变体；说非当地主要语言的人〔特定地区用法〕','同一个语言单位，在不同位置可以穿上不同的发音外衣。','语言学用 allo- “别的、不同的” + -phone“声音”；加拿大社会语言用法又与法语 allophone“说别种语言的”相连。',P+[['英语 allo- + -phone → allophone〔语音学〕','同一个音位的不同发音实现'],['并列：法语 allophone → 加拿大英语 allophone〔人群称谓〕','母语不是当地指定主要语言的人']],'英语 pin 词首送气的 [pʰ] 和 spin 里的不送气 [p]，通常算 /p/ 的变体。加拿大说 allophone 时，常指母语既非法语也非英语的人，具体分类是否另列原住民语言要看使用规范。','an allophone of /p/；allophonic variation；an allophone community。','allophone 不是“发错的音”；它可以是完全正常、由语境决定的读法。人群义并不指一个人“有多个口音”。',('The aspirated sound is an allophone of /p/ in this language.','这个送气音在该语言中是 /p/ 的一个音位变体。'),('The lesson compares the two allophones using slow recordings.','这节课用慢速录音比较这两个音位变体。'),sources=['https://en.wiktionary.org/wiki/allophone#English']),
E('homophone','英 /ˈhɒməfəʊn/；美 /ˈhɑːməfoʊn/','同音词','听起来一样，意思或拼写却可以不同，耳朵不能单独帮你分清。','借法语 homophone，远接希腊 homós“相同” + phōnḗ“声音”；现代可分析 homo- + -phone。',HO+[['法语 homophone → 英语 homophone','同样发音的词或符号']],'sea 和 see 是常见例子。是否同音取决于口音：某两词在一种口音中同音，在另一种中可能不同。拼写不同很常见，但“同音”这个判断本身依靠声音。','a pair of homophones；confuse homophones；a homophone of。','homograph 看拼写相同；homophone 看发音相同。一个词对可以兼有不同关系。',('Sea and see are homophones in standard English.','在标准英语中，sea 与 see 是同音词。'),('The joke depends on a homophone that disappears in translation.','这个笑话依赖一对同音词，翻译后这层效果就消失了。'),sources=['https://en.wiktionary.org/wiki/homophone#English']),
E('homophonous','英 /həˈmɒfənəs/；美 /həˈmɑːfənəs/','同音的','把两个词放在声音这一栏里比较，结果听上去重合。','希腊 homóphōnos 经英语形容词形式 -ous 调整；不是把现代名词 homophone 当作唯一历史起点。',HO+[['希腊 homóphōnos + 英语 -ous 形式 → homophonous','发音相同的']],'这是一种关系：word A is homophonous with word B。比较时最好说明口音和所指读法，特别是多音词。','homophonous with；homophonous words；homophonous forms。','homophonous 常用于语言中的同音；homophonic 在音乐中还指主调织体，不能见到 homo- 就套同一个译法。',('The two forms are homophonous in her dialect.','在她的方言里，这两个形式同音。'),('A spelling change made the words look different, although they remained homophonous.','拼写变化让两个词看起来不同了，但它们依旧同音。'),sources=['https://en.wiktionary.org/wiki/homophonous#English']),
E('phonotactics','英 /ˈfəʊnətæktɪks/；美 /ˈfoʊnətæktɪks/','音系配列；音位组合规则的研究','不是任何声音都能随便排队；每种语言都有自己的队列规矩。','phono- “声音” + tactics“排列、组织”；后者远接希腊表示安排的词族，这里不是军事谋略。',P+[['英语 phono- + tactics → phonotactics','研究语音单位在语言中怎样组合、哪些组合被限制']],'英语可以有词首 /str/，却通常不接受词首 /ŋ/。这种限制说的是语言习惯，不是人的嘴绝对发不出来。借词也常因本地规则而调整读音。','English phonotactics；phonotactic constraints；the phonotactics of a language。','phonetics 问能怎样发声；phonotactics 问某种语言容许怎样组合，发得出不等于本来就在该语言中。',('The invented name follows English phonotactics.','这个编造的名字符合英语的音系组合习惯。'),('Their study compares word-initial clusters and phonotactics across languages.','他们的研究比较不同语言的词首辅音组合及音系配列规则。'),sources=['https://en.wiktionary.org/wiki/phonotactics#English']),
E('morphophonology','英 /ˌmɔːfəʊfəˈnɒlədʒi/；美 /ˌmɔːrfoʊfəˈnɑːlədʒi/','形态音系学','把词的零件拼起来时，发音也会随接缝改变，研究的就是这个接口。','morpho- “形式、词形” + phonology；结合词形结构与音系规律。',PL+[['英语 morpho- + phonology → morphophonology','研究词素组合、词形变化与语音变化的相互作用']],'英语复数词尾在 cats、dogs、buses 中读法不同，便能用来说明词形与发音怎样交互。关注的是词素在环境中的表现，不是只研究字母长相。','English morphophonology；a study of morphophonology。','morphology 看词怎样由有意义单位组成；phonology 看声音系统；morphophonology 专看两者交接处。',('The plural endings provide a useful introduction to English morphophonology.','复数词尾是理解英语形态音系学的好入口。'),('The course connects word formation with morphophonology.','课程把构词与形态音系学联系起来讲。'),sources=['https://en.wiktionary.org/wiki/morphophonology#English']),
E('archiphoneme','英 /ˈɑːkɪfəʊniːm/；美 /ˈɑːrkɪfoʊniːm/','大音位；中和音位','两个原本不同的音位，在某个位置不再作区分，于是用一个上层记号概括它们的共同点。','现代术语借德语 Archiphonem 或法语 archiphonème，archi- 加 phoneme；现代可拆，并非古希腊现成概念。',PM[:-1]+[['希腊 phṓnēma → 法语 phonème／德语 Phonem','发出的声音 → 现代音位概念'],['德语 Archiphonem／法语 archiphonème → 英语 archiphoneme','用上层单位描述某位置被中和的音位对立']],'以德语某些词末清浊对立中和为例，一套分析可用大写 /T/ 概括 /t/ 与 /d/ 的共同特征。它是特定音系理论的分析工具，不是说话时另加一个神秘的声音。','an archiphoneme；represent an archiphoneme；phonemic neutralization。','allophone 是一个音位的实际变体；archiphoneme 是在对立中和时概括多个音位的分析单位。',('The analysis uses /T/ as an archiphoneme in word-final position.','这项分析用 /T/ 作为词末位置的大音位。'),('The archiphoneme records the features shared by the two consonants.','这个大音位记下了两个辅音共有的特征。'),sources=['https://www.dictionary.com/browse/archiphoneme','https://dictionary.cambridge.org/pronunciation/english/archiphoneme']),
E('apophony','英 /əˈpɒfəni/；美 /əˈpɑːfəni/','元音交替；词内元音变换','不用只在词尾加东西，改一改词内部的元音，也能标出词形差别。','借法语 apophonie，apo- “离开、改变” + 希腊 phōnḗ“声音”；不是英语 apology 的变体。',H+[['法语 apo- + -phonie → apophonie → 英语 apophony','以内部元音变化表示词形或相关词的差别']],'sing、sang、sung 里的元音交替是直观例子。这个术语着眼于词根内部的变化，不是普通说快了造成的任意模糊发音。','vowel apophony；patterns of apophony；an example of apophony。','ablaut 常与 apophony 接近；umlaut 特指另一类受相邻音影响的历史元音变化，不能把所有元音变化都当成同一过程。',('Sing, sang, and sung illustrate apophony.','sing、sang 和 sung 展示了元音交替。'),('The chapter explains how apophony marks different grammatical forms.','这一章解释元音交替如何标记不同的语法形式。'),sources=['https://en.wiktionary.org/wiki/apophony#English']),
E('isophone','英 /ˈaɪsəfəʊn/；美 /ˈaɪsəfoʊn/','等音线；语音分界线','在地图上画一条线，标出某种发音现象分布到哪里。','iso- “相同” + phone“声音”；这里的 phone 是语音成分，不是电话。',P+[['英语 iso- + phone → isophone','以某一发音特征划出的地理分界']],'例如调查某个元音在各地的读法，可以用 isophone 标出一类读法的范围。不同特征的线可能不重合，所以一条线不能代表整个方言的一切边界。','draw an isophone；an isophone on a dialect map。','isogloss 是语言特征分界线的总称，可关乎词汇或语法；isophone 专指发音特征。',('The isophone separates areas with two different pronunciations of the vowel.','这条等音线分开了该元音两种读法的分布地区。'),('Several isophones cross the same region without forming a single boundary.','多条等音线穿过同一地区，却没有合成一条统一边界。'),sources=['https://www.dictionary.com/browse/isophone','https://en.wiktionary.org/wiki/isophone#English'])
])
W.extend([
E('symphony','/ˈsɪmfəni/','交响曲；交响乐团〔简称〕；和谐的组合','许多声音组织在一起，形成一个有展开、有层次的整体。','希腊 syn- “一起” + phōnḗ，经 symphōnía、拉丁和法语进入英语；早期并不专指今天的交响曲。',SY,'现代通常指为管弦乐队写成的较大型作品，常分几个乐章；不能硬规定所有交响曲都恰好四个乐章。a symphony of colours 则借和谐组合的画面形容色彩。','compose a symphony；a symphony orchestra；a symphony of colours。','orchestra 是演奏的乐队；symphony 通常是作品，但有时省略 orchestra 而代指乐团。',('The orchestra will perform her new symphony tonight.','乐队今晚将演奏她的新交响曲。'),('The garden became a symphony of red and gold in autumn.','秋天的花园成了红色与金色和谐交织的景象。'),sources=['https://en.wiktionary.org/wiki/symphony#English','https://www.etymonline.com/word/symphony']),
E('symphonic','英 /sɪmˈfɒnɪk/；美 /sɪmˈfɑːnɪk/','交响曲的；交响乐式的','声音在规模、配器或展开方式上带有交响音乐的特点。','现代可按 symphony + -ic；部分用法也可能受法语 symphonique 影响，不必把所有出现都限定成同一种派生路线。',SY+[['英语 symphony + -ic → symphonic；亦受法语 symphonique 影响','交响曲的；具有交响音乐特点的']],'symphonic music 可以泛指有交响风格的管弦乐。symphonic poem 是交响诗，不因带 symphonic 就自动变成多乐章交响曲。','symphonic music；a symphonic poem；symphonic writing。','symphony 是作品名称；symphonic 是性质形容词，适用范围更宽。',('The film score has a rich symphonic sound.','这部电影的配乐具有丰富的交响音色。'),('She adapted the song into a symphonic poem.','她把这首歌改编成了一首交响诗。'),sources=['https://www.etymonline.com/word/symphonic','https://en.wiktionary.org/wiki/symphonic#English']),
E('polyphonic','英 /ˌpɒlɪˈfɒnɪk/；美 /ˌpɑːliˈfɑːnɪk/','复调的；能同时发多音的；多声部的','几条旋律各有自己的路线，却能一起进行。','英语据希腊 polýphōnos“多声的”形成 -ic 形容词；现代可看 poly- “多” + -phonic。音乐形容词出现早于相关名词的特定音乐义。',H+[['希腊 polýs + phōnḗ → polýphōnos → 英语 polyphonic','多声的 → 多条独立旋律并行；设备可同时发多音']],'复调织体不只是很多人一起唱同一条旋律。合成器规格里的 polyphonic 则常只说能同时响几个音，并不保证演奏出来的作品属于复调音乐。','polyphonic music；a polyphonic texture；a polyphonic synthesizer。','stereophonic 说声道与空间重放；polyphonic 可以说旋律关系或同时发音能力，标准不同。',('The fugue develops a dense polyphonic texture.','这首赋格逐渐展开密集的复调结构。'),('A polyphonic synthesizer can play several notes at once.','复音合成器能同时发出几个音。'),sources=['https://www.etymonline.com/word/polyphonic','https://en.wiktionary.org/wiki/polyphonic#English']),
E('polyphony','英 /pəˈlɪfəni/；美 /pəˈlɪfəni/','复调；多声部；设备的复音能力','同时响着的几条线索，各自有方向，不只是给一个主角铺背景。','希腊 polyphōnía“多种声音”进入英语；专门的音乐名词义也可能受较早 polyphonic 反向形成的影响。',H+[['希腊 polýphōnos → polyphōnía → 英语 polyphony','多声 → 多种声音'],['英语音乐用法：polyphonic 与 polyphony 相互关联','多条独立旋律共同展开；名词音乐义可能从形容词反构']],'音乐课上的 polyphony 常说复调组织。键盘上的 64-note polyphony 常说同时可维持的发音数量。文学评论也借它说多种独立声音并存，要看讨论对象。','Renaissance polyphony；rich polyphony；maximum polyphony。','homophony 常有主旋律与和声支撑；polyphony 更看重多条线的相对独立。',('The class listened for the independent melodies within the polyphony.','课堂上，大家辨听复调音乐中各自独立的旋律。'),('Using the sustain pedal can increase the demand on a keyboard’s polyphony.','使用延音踏板会增加对键盘复音能力的需求。'),sources=['https://www.etymonline.com/word/polyphonic','https://en.wiktionary.org/wiki/polyphony#English']),
E('monophonic','英 /ˌmɒnəˈfɒnɪk/；美 /ˌmɑːnəˈfɑːnɪk/','单声部的；单声道的；单音的','“一”要先问在数什么：一条旋律、一个声道，还是一次只能发一个音。','mono- “单一” + -phonic “声音的”；音乐与录音技术把同一组合用于不同分类。',P+[['英语 mono- + -phonic → monophonic','单一声音路线；后来分别用于织体、声道与设备能力']],'一群人齐唱同一旋律可以是单声部，虽然人数很多；一支乐队的录音也可以是单声道，虽然实际有许多旋律。两种“一”不能混算。','a monophonic chant；a monophonic recording；a monophonic synthesizer。','polyphonic 常对照多旋律或多音能力；stereophonic 在录音里与单声道形成对照。',('The choir began with a monophonic chant sung in unison.','合唱团以齐唱的一段单声部圣咏开始。'),('The old broadcast survives only as a monophonic recording.','那段旧广播只留下了单声道录音。'),sources=['https://en.wiktionary.org/wiki/monophonic#English','https://viva.pressbooks.pub/openmusictheory/chapter/texture/']),
E('monophony','英 /məˈnɒfəni/；美 /məˈnɑːfəni/','单声部织体；单旋律音乐','所有音乐注意力沿着同一条旋律走，没有另一条和声或对位线同时陪着。','mono- “单一” + -phony “声音状态”；与 monophonic 对应的音乐名词。',P+[['英语 mono- + -phony → monophony','单一旋律线的音乐组织']],'不一定只有一个演奏者：许多人齐唱同一条旋律仍可构成 monophony。判断的是实际音乐线条，不是舞台上的人数。','unaccompanied monophony；examples of monophony；from monophony to polyphony。','单声道录音可以装下复杂复调，monophony 的音乐织体义不等于 mono recording。',('The opening is an example of monophony, with everyone singing the same melody.','开头是单声部的例子，所有人都唱同一旋律。'),('The piece moves from monophony to a melody with chordal accompaniment.','作品从单声部逐渐转为主旋律配和弦伴奏。'),sources=['https://www.merriam-webster.com/dictionary/monophony','https://en.wiktionary.org/wiki/monophony#English']),
E('homophony','英 /həˈmɒfəni/；美 /həˈmɑːfəni/','主调织体；同音关系〔语言学〕','音乐里，各声部围绕共同的和声行动，常由一条旋律带头；语言里则是发音相同。','希腊 homophōnía“齐声、同声”经法语 homophonie 等学术用法进入英语。',HO+[['法语 homophonie → 英语 homophony','同声 → 主调音乐组织；同音关系']],'常见画面是主旋律在前，和弦伴奏在后支撑。各声部不必每个节拍都完全同进同退，旋律加伴奏也属于常见主调。语言学里的 homophony 则回到两个形式同音的关系。','homophony and polyphony；a passage of homophony；lexical homophony。','homophony 不是所有人唱同一个音高；只有一条旋律、无独立伴奏的情况通常叫 monophony。',('The song uses homophony, with a clear melody above simple chords.','歌曲采用主调织体，清楚的主旋律由简单和弦伴奏支撑。'),('The pun relies on homophony between two unrelated words.','这个双关依赖两个不相关词的同音关系。'),sources=['https://en.wiktionary.org/wiki/homophony#English','https://viva.pressbooks.pub/openmusictheory/chapter/texture/']),
E('homophonic','英 /ˌhɒməˈfɒnɪk/；美 /ˌhɑːməˈfɑːnɪk/','主调的；同音的','在音乐里是声音彼此配合、让主线显出来；在词语里是听起来一样。','homo- “相同” + -phonic；与希腊 homóphōnos“同声的”和现代 homophony 同族。',HO+[['英语 homo- + -phonic → homophonic','同声的；在音乐中用于主调关系']],'a homophonic setting 常让旋律得到和声支持。a homophonic pun 则是利用同音制造双关，同一个形容词在两个领域需要不同译法。','a homophonic texture；a homophonic setting；a homophonic pun。','polyphonic 让几条旋律各保有独立性；homophonic 常让声部服务于主旋律或共同和声。',('The hymn has a largely homophonic texture.','这首赞美诗大体采用主调织体。'),('The title contains a homophonic pun that is hard to translate.','标题中有一个很难翻译的同音双关。'),sources=['https://www.merriam-webster.com/dictionary/homophonic','https://viva.pressbooks.pub/openmusictheory/chapter/texture/']),
E('heterophony','英 /ˌhetəˈrɒfəni/；美 /ˌhetəˈrɑːfəni/','支声织体；同一旋律的变体同时演奏','大家沿着同一条曲调走，却各自加一点装饰或变化，像同路人走出略有不同的步子。','希腊 heterophōnía 进入英语，hetero- “不同” + phōnḗ“声音”；现代音乐义比字面“不同声”具体。',H+[['希腊 héteros + phōnḗ → heterophōnía → 英语 heterophony','不同声音；现代指同一旋律的多个变体同时出现']],'一人拉出基本曲调，另一人同时加经过音或装饰，而主线仍认得出来，这就是理解 heterophony 的好画面。它不是演奏不整齐的自动名称。','a passage of heterophony；heterophony in an ensemble。','polyphony 通常有相对独立的多条旋律；heterophony 是同一条旋律的不同版本同时展开。',('The flute ornaments the tune while the violin plays it plainly, creating heterophony.','长笛给曲调加装饰，小提琴同时直奏基本旋律，形成支声织体。'),('The class compared heterophony with strict unison singing.','课堂上比较了支声织体与严格齐唱。'),sources=['https://en.wiktionary.org/wiki/heterophony#English','https://viva.pressbooks.pub/openmusictheory/chapter/texture/']),
E('heterophonic','英 /ˌhetərəˈfɒnɪk/；美 /ˌhetərəˈfɑːnɪk/〔按构词读音〕','支声的；同一旋律变体并行的','几个声部基本唱同一件事，但细节不完全一样。','heterophony 对应 -phonic 的形容词形式；hetero- 与 -phonic 分别指不同和声音。',H+[['希腊 heterophōnía → 英语 heterophony → heterophonic','同一旋律变体并行 → 描述这种音乐组织的形容词']],'heterophonic texture 强调旋律变体同时出现。如果只是先演奏一遍原曲、再演奏一遍变奏，并不因此就算 heterophonic。','a heterophonic texture；heterophonic performance；heterophonic variation。','heterophonic 的关键是同时并行；普通 variation 可以一段接一段，不必重叠。',('The two instruments produce a heterophonic version of the melody.','两件乐器同时演奏旋律的不同版本，形成支声效果。'),('The arrangement keeps the heterophonic details of the original performance.','编曲保留了原演奏中各声部的支声细节。'),sources=['https://www.dictionary.com/browse/heterophonic','https://en.wiktionary.org/wiki/heterophonic#English']),
E('antiphon','英 /ˈæntɪfən/；美 /ˈæntɪfɑːn/','应答圣歌；对经；回应','一边唱出一句，另一边用一句接住，让声音形成来回。','希腊 anti- 在此是“回应”，经 antíphōna、拉丁 antiphona，再从法语 antiphone 或拉丁语借入英语。',AN+[['法语 antiphone／中世纪拉丁 antiphona → 英语 antiphon','应答唱诵的短句或乐曲；较晚的重新借入']],'教会礼仪中常指与诗篇等搭配的短句或圣歌，未必每次实际演唱都严格由两队交替。历史的回应画面帮助记忆，具体形式要看礼仪。','sing an antiphon；an antiphon before a psalm。','anti- 在这里不是“反对声音”。anthem 是同源早借词演变而来，现代意义已经更宽。',('The choir sang an antiphon before the psalm.','合唱团在诗篇前唱了一段对经。'),('The same antiphon returned at the end of the service.','礼拜结束时，同一段应答圣歌再次响起。'),sources=['https://www.etymonline.com/word/antiphony','https://en.wiktionary.org/wiki/antiphon#English']),
E('antiphony','/ænˈtɪfəni/','对答式歌唱；交替应答','声音从一组传到另一组，像有来有回的对话。','英语 antiphon + -y；现代名词说应答的方式或整体过程。',AN+[['法语／拉丁 → 英语 antiphon → antiphony','应答圣歌 → 两组交替回应的演唱方式']],'两个合唱组轮流唱是典型画面。文学描写也可以把交替的呼声、观点称为 antiphony，借的是相互应答的结构。','choral antiphony；antiphony between two groups。','antiphon 可指一段具体圣歌；antiphony 更突出声音怎样交替。它不是 cacophony“杂乱噪声”。',('The two choirs created an antiphony across the hall.','两组歌者隔着大厅交替应唱。'),('The passage uses antiphony between the soloist and the chorus.','这段音乐让独唱者与合唱队交替应答。'),sources=['https://www.etymonline.com/word/antiphony','https://www.merriam-webster.com/dictionary/antiphony']),
E('anthem','/ˈænθəm/','颂歌；国歌；代表某群体的歌曲','一群人用一首歌表达共同的认同、赞颂或愿望。','拉丁 antiphona 等形式很早进入古英语 antefn / antefen，再经中古英语 anteme 演变；th 是后来拼写和读音变化，不是希腊原词有 th。',AN+[['后期拉丁 antefana 等变体 → 古英语 antefn / antefen → 中古英语 anteme','应答歌唱逐渐演为宗教赞歌'],['英语 anthem','th 后起；颂歌 → 国歌、群体代表歌曲']],'national anthem 是国歌；an anthem for a generation 可指一代人的代表歌。它不一定属于宗教，也不必采用交替应答唱法，意义已走得很远。','a national anthem；sing the anthem；an anthem for a movement。','antiphon 是后来再借入、保留更多旧形的词；anthem 不是英语里直接删掉 antiphon 几个字母得到的缩写。',('The crowd stood as the national anthem began.','国歌响起时，人群站了起来。'),('The song became an anthem for young people seeking change.','这首歌成了渴望改变的年轻人的代表歌曲。'),sources=['https://www.etymonline.com/word/anthem','https://en.wiktionary.org/wiki/anthem#English']),
E('diaphony','英 /daɪˈæfəni/；美 /daɪˈæfəni/','不协和；早期复调形式〔音乐史〕','声音不完全重合，彼此拉开；音乐史里也用它称某些早期多声部写法。','希腊 dia- + phōnḗ → diaphōnía“声音不合、分歧”；英语早有“不协和”义，后来用于中世纪音乐。',H+[['希腊 diaphōnía → 中世纪拉丁 diaphonia → 英语 diaphony','不同声、声音不合 → 不协和'],['英语音乐史用法 diaphony','用于早期 organum 等多声部形式，术语范围因作者而异']],'常见介绍会联系声部按四度、五度或八度平行移动的早期写法；不同史书使用范围不完全一样。不要见到 dia- 就机械翻成“两个声音”，它不是数字 di-。','medieval diaphony；a discussion of diaphony。','diphony 的 di- 可指二；diaphony 的 dia- 来自另一组合。现代讨论某作品时，最好说明具体声部写法。',('The lecture linked medieval diaphony with early forms of organum.','讲座把中世纪的 diaphony 与早期奥尔加农形式联系起来。'),('The historian explains what she means by diaphony before analysing the example.','历史学者先解释自己所说的 diaphony 是什么，再分析例子。'),sources=['https://www.etymonline.com/word/diaphony','https://www.merriam-webster.com/dictionary/diaphony']),
E('euphony','/ˈjuːfəni/','悦耳；音韵和谐','一些声音排在一起，念着顺、听着舒服。','希腊 eu- “好” + phōnḗ“声音”形成 euphōnía，经法语 euphonie 借入。',EU,'常用来评价文字、诗句或名称的音响效果。语音史中也有人用它讨论为了顺口而发生的调整；“悦耳”带有听者和语言习惯的影响，不是普遍固定的声音等级。','the euphony of a phrase；choose a name for its euphony。','euphemism 是委婉表达，关心话怎么说得不刺人；euphony 关心声音听起来是否和谐。',('The poet chose the phrase for its euphony as well as its meaning.','诗人选择这个短语，既考虑意思，也考虑音韵是否悦耳。'),('Reading the line aloud reveals its euphony.','把这一行读出来，就能听出它的音韵和谐。'),sources=['https://en.wiktionary.org/wiki/euphony#English']),
E('euphonic','英 /juːˈfɒnɪk/；美 /juːˈfɑːnɪk/','悦耳的；有谐音效果的','声音相接时顺畅、协调，适合用来形容音韵效果。','euphony 对应 -ic 形容词，远接希腊“好声音”。',EU+[['英语 euphony → euphonic','悦耳 → 与悦耳效果有关、具有这种效果的']],'euphonic effect 可说诗句的声音效果；euphonic change 是语音讨论中一种以顺口、和谐解释的变化说法。它不像 happy 那样描述说话者的心情。','a euphonic effect；euphonic changes；a euphonic sequence。','euphonious 与它接近，常直接说声音好听；euphonic 在技术、音韵讨论中也常见。',('The repeated vowels give the line a euphonic quality.','重复的元音让这一行具有悦耳的音韵效果。'),('The editor preferred the more euphonic version of the title.','编辑更喜欢那个念起来更顺耳的标题版本。'),sources=['https://en.wiktionary.org/wiki/euphonic#English']),
E('euphonious','英 /juːˈfəʊniəs/；美 /juːˈfoʊniəs/','悦耳的；声音和谐的','不只是在发声，而是让人愿意继续听下去。','与 euphony、euphonic 同族；有从较早 euphonical 调整为 -ous 形容词的分析，远接希腊 eu- + phōnḗ。',EU+[['英语 euphonic / euphonical → euphonious','形容悦耳效果的相关形式；-ous 表示具有该性质']],'可形容嗓音、乐句、名字或文字组合。它比较书面，日常通常直接说 pleasant-sounding 或 sounds nice；并不专门等于“音乐演奏得正确”。','a euphonious voice；a euphonious name；euphonious phrases。','euphonious 与 cacophonous 在听感上对照；同样一句话的意思美好，不代表声音一定 euphonious。',('She chose a short, euphonious name for the character.','她给角色选了一个简短悦耳的名字。'),('The flute and cello formed a euphonious blend.','长笛和大提琴交织出悦耳的音色。'),sources=['https://en.wiktionary.org/wiki/euphonious#English']),
E('euphonize','/ˈjuːfənaɪz/','使悦耳；使音韵协调〔少见〕','改一改声音的排列，让它念起来、听起来更顺。','euphony + -ize，表示使具有悦耳的效果。',EU+[['英语 euphony + -ize → euphonize','把声音调整得更和谐']],'多见于讨论措辞、语音或音乐的较旧、较书面文本。它说的是调整声音效果，不一定改变文字的意义。','euphonize a phrase；euphonize a name。','euphemize 是改成委婉说法；euphonize 是让声音好听，可能只动音节或选词。',('The translator changed the word order to euphonize the line.','译者调整词序，使这一行读起来更悦耳。'),('The author tried to euphonize the invented name without changing its meaning.','作者试着让这个自创名字更顺耳，同时保留它的含义。'),sources=['https://www.merriam-webster.com/dictionary/euphonize','https://en.wiktionary.org/wiki/euphonize#English']),
E('cacophony','英 /kəˈkɒfəni/；美 /kəˈkɑːfəni/','刺耳的杂声；乱哄哄的声音','许多声音挤在一起，互相打架，听着难以分清。','希腊 kakós“坏、不好” + phōnḗ → kakophōnía，经法语 cacophonie 借入。',[['希腊 kakós〔不好〕与 phōnḗ〔声音〕','两份构词材料并列'],['希腊 kakophōnía → 法语 cacophonie → 英语 cacophony','不悦耳的声音组合']],'喇叭、叫喊、机器声混作一团可成 cacophony。a cacophony of opinions 则比喻观点吵成一片；不要求所有声音都极大，只要混乱刺耳。','a cacophony of horns；a sudden cacophony；a cacophony of voices。','noise 可以泛指噪声；cacophony 更生动地表现多种声音不协调地挤在一起。',('A cacophony of horns rose from the blocked street.','堵住的街道上传来一片刺耳的喇叭声。'),('The quiet room suddenly became a cacophony of ringing phones.','安静的房间突然被杂乱的电话铃声淹没。'),sources=['https://en.wiktionary.org/wiki/cacophony#English']),
E('cacophonous','英 /kəˈkɒfənəs/；美 /kəˈkɑːfənəs/','刺耳杂乱的；不协调的','不是单说声响很大，而是声音互相冲撞、让耳朵难受。','希腊 kakóphōnos“难听的”以英语 -ous 形容词形式借入；现代可认出 caco- 与 -phonous。',[['希腊 kakós〔不好〕与 phōnḗ〔声音〕','两份构词材料并列'],['希腊 kakóphōnos → 英语 cacophonous','难听的 → 刺耳不协调的']],'cacophonous music 可指故意制造的刺耳效果，也可表达听者不喜欢。形容词在评价声音，不自动说明创作者没有技巧。','cacophonous noise；a cacophonous street；a cacophonous mixture。','loud 只说响；cacophonous 说不协调、难听。很响的合唱可以很悦耳。',('The instruments produced a deliberately cacophonous opening.','这些乐器有意奏出一个刺耳杂乱的开头。'),('We left the cacophonous market for a quiet side street.','我们离开嘈杂刺耳的市场，走进一条安静的小街。'),sources=['https://en.wiktionary.org/wiki/cacophonous#English']),
E('idiophone','英 /ˈɪdiəfəʊn/；美 /ˈɪdiəfoʊn/','体鸣乐器','发声的关键是乐器本体在振动，而不是另绷一张膜或一根弦。','idio- “自身、特有的” + -phone“声音”；是近代乐器分类名称。',P+[['英语 idio- + -phone → idiophone','靠自身材料振动发声的乐器类别']],'钟、锣、木琴都是容易理解的例子。鼓虽然常用敲击演奏，主要振动的是鼓膜，通常归膜鸣乐器；“打击乐”与“体鸣”不是完全同一分类。','a struck idiophone；metal idiophones；classify an idiophone。','ideophone 是描摹感官印象的词；idiophone 是乐器，只差一个字母，学科却不同。',('A bell is an idiophone because its metal body vibrates.','钟是体鸣乐器，因为振动发声的是金属本体。'),('The collection includes idiophones made from wood, metal, and stone.','这批藏品包含由木材、金属和石头制成的体鸣乐器。'),sources=['https://en.wiktionary.org/wiki/idiophone#English'])
])
W.extend([
E('phonogram','英 /ˈfəʊnəɡræm/；美 /ˈfoʊnəɡræm/','表音符号；录音制品、声音记录','把听到的声音留下来：可以用文字符号表示，也可以真正录成声音。','phono- “声音” + -gram“写下的东西”；近代组合词的两种用法分别落在文字与录音领域。',P+[['英语 phono- + -gram → phonogram','表示声音的书写符号；记录下来的声音']],'文字学里的 phonogram 是表示读音的符号，可代表一个或多个音；唱片文献里的 phonogram 则是声音记录，不限于某一种实体盘片。','a phonogram in a script；a recorded phonogram；phonogram production。','phonograph 通常是机器；phonogram 是表示或记录的结果，像“记录器”与“记录物”的差别。',('The sign functions as a phonogram rather than a picture of the object.','这个符号用来表音，而不是画出物体。'),('The archive catalogues each phonogram with its recording date.','档案馆为每份声音记录登记录制日期。'),sources=['https://en.wiktionary.org/wiki/phonogram#English']),
E('acrophony','英 /əˈkrɒfəni/；美 /əˈkrɑːfəni/','首音命名法；截头表音原则','拿一个熟悉事物的名字，只取它开头的声音，去给符号赋值。','acro- 接希腊 ákros“顶端、起头” + -phony“声音”；是近代讨论文字系统的术语。',H+[['希腊 ákros → acro- + -phony → 英语 acrophony','用名称开头的声音为符号命名或赋予音值']],'假设把“门”的图形只用来表示门这个词的第一个音，就是这个原则的简化示意。现代字母教学说 B for ball 也利用词首声音帮助辨认，但不等于所有现代字母都由这幅图历史演变而来。','the principle of acrophony；acrophony in alphabet development。','acronym 从多个词的首字母构成缩略词；acrophony 取一个名称的开头声音来联系符号。',('The lesson explains acrophony with a picture whose name begins with the target sound.','课堂用一个名称以目标音开头的图形来解释首音原则。'),('Acrophony helped give some early alphabetic signs their sound values.','首音原则帮助某些早期字母符号获得了音值。'),sources=['https://www.merriam-webster.com/dictionary/acrophony','https://en.wiktionary.org/wiki/acrophony#English']),
E('acrophonic','英 /ˌækrəˈfɒnɪk/；美 /ˌækrəˈfɑːnɪk/','首音命名的；按名称开头声音表音的','符号表示的声音，来自该符号所命名事物的开头。','acro- “起头” + -phonic“声音的”，与 acrophony 对应；英语形容词见证早于常列名词年代，不把名词到形容词的现代对应硬说成唯一历史顺序。',H+[['近代 acro- + -phonic → 英语 acrophonic','按名称的第一个音建立符号对应；与 acrophony 形成术语组']],'acrophonic principle 描述一种符号命名或取音原则。它不是“高音的”：acro- 在这里抓的是起头，不是音调高低。','an acrophonic principle；an acrophonic name；an acrophonic sign。','phonetic 泛指与语音有关；acrophonic 指一种很具体的用词首音联系符号的方法。',('The chart uses an acrophonic method to teach the letter sounds.','这张表用名称首音的方法教授字母发音。'),('The researcher tests whether the sign had an acrophonic value.','研究者检验这个符号是否曾有按名称首音取得的音值。'),sources=['https://www.merriam-webster.com/dictionary/acrophonic','https://www.merriam-webster.com/dictionary/acrophony']),
E('misophonia','英 /ˌmɪsəˈfəʊniə/；美 /ˌmɪsəˈfoʊniə/','厌声症；对特定声音的耐受显著降低','某些特定声音一出现，就会引起很强的烦躁、厌恶或身体反应，音量未必很大。','现代 miso- “厌恶” + -phonia“声音状态”，两部分来自希腊语；不是日语味噌 miso。',P+[['现代 miso- + -phonia → misophonia','对特定声音的低耐受与强烈反应']],'例如对某种重复咀嚼声出现强烈反应，关心的是声音的模式和个人感受，不能只量它多响。这个术语不等于任何一次嫌人吵，也不能把当事人的反应简单理解成“故意挑剔”。','misophonia triggers；live with misophonia；research on misophonia。','phonophobia 可侧重怕声音或对声音敏感；misophonia 更突出特定触发声引出的负面反应，不能只按字面互换。',('The study asked people with misophonia to describe their trigger sounds.','研究请有厌声症的人描述哪些声音会触发他们的反应。'),('Her misophonia was triggered by a quiet, repetitive sound rather than a loud noise.','触发她厌声反应的是轻而重复的声音，而不是很大的噪声。'),sources=['https://www.frontiersin.org/journals/neuroscience/articles/10.3389/fnins.2022.841816/full','https://en.wiktionary.org/wiki/misophonia#English']),
E('dysphonia','英 /dɪsˈfəʊniə/；美 /dɪsˈfoʊniə/','发声障碍；嗓音异常','想把声音发出来，却在音质、音高、响度或用力程度上出现异常。','dys- “困难、异常” + -phonia“发声”；使用希腊声音成分形成医学术语。',H+[['医学构词 dys- + -phonia → dysphonia','发声功能或嗓音质量出现问题']],'可能表现为沙哑、气息声、费力或声音不稳。它描述嗓音问题，原因有多种，不等于每次沙哑都能仅凭一个词确定具体病因。','persistent dysphonia；muscle tension dysphonia；assessment of dysphonia。','aphonia 强调失声；dysphonia 范围较广。aphasia 则关乎语言功能，不能把嗓子与理解表达能力混为一谈。',('The report describes dysphonia as a change in voice quality.','报告把发声障碍描述为嗓音质量的变化。'),('The clinician assessed the degree of dysphonia during sustained vowels.','临床人员通过持续发元音评估嗓音异常的程度。'),sources=['https://www.asha.org/practice-portal/clinical-topics/voice-disorders','https://en.wiktionary.org/wiki/dysphonia#English']),
E('aphonia','英 /eɪˈfəʊniə/；美 /eɪˈfoʊniə/；亦可弱读开头 /ə-/','失声','语言可能仍在心里，也可能还能写字，却无法正常发出嗓音。','希腊 a- “无” + phōnḗ → aphōnía，经新拉丁 aphonia 借入医学英语。',H+[['希腊 aphōnía → 新拉丁 aphonia → 英语 aphonia','无声、不能发声 → 失声']],'失声不等于完全失去沟通能力，也不一定失去语言理解能力；有些情况下仍能耳语。词里 a- 否定的是声音，不是思想或人格。','temporary aphonia；functional aphonia；loss of voice。','aphasia 是失语，涉及语言功能；aphonia 是失声。中文差一个字，指向的功能不同。',('Aphonia prevented her from speaking in her usual voice.','失声使她无法用平常的嗓音说话。'),('The patient with aphonia communicated by writing.','这位失声的患者通过书写沟通。'),sources=['https://www.asha.org/practice-portal/clinical-topics/voice-disorders','https://en.wiktionary.org/wiki/aphonia#English']),
E('aphonic','英 /eɪˈfɒnɪk/；美 /eɪˈfɑːnɪk/；亦可弱读开头 /ə-/','失声的；无声的；清音的〔术语用法〕','声音没有按通常方式发出，或在特定术语里缺少声带振动。','a- “无” + phonic“声音的”，与 aphonia 同族；不是英语 phony“假的”加前缀。',P+[['英语 a- + phonic → aphonic','没有声音的；与失声状态有关']],'医学 a person is aphonic 是说该人处于失声状态；较旧语音用法也可表示清音。用到具体文章里，要看它在谈整个人的嗓音还是一个语音的性质。','an aphonic patient；remain aphonic；aphonic speech。','silent 可以是主动不说话；aphonic 说无声或失声性质，不等于“不愿意开口”。',('She remained aphonic during the interview and wrote her answers.','访谈时她仍处于失声状态，用写字回答。'),('The textbook contrasts aphonic and voiced sounds in its older terminology.','这本教材用较旧术语对照清音与浊音。'),sources=['https://www.merriam-webster.com/dictionary/aphonic','https://en.wiktionary.org/wiki/aphonic#English']),
E('diplophonia','英 /ˌdɪpləˈfəʊniə/；美 /ˌdɪpləˈfoʊniə/','双重嗓音；双音发声','一个人的嗓音里，似乎同时叠着两个不同音高。','新拉丁医学组合 diplo- “双” + 希腊声音成分 + -ia；不是两个人合唱的名称。',H+[['新拉丁 diplo- + phōn- + -ia → diplophonia → 英语','一个嗓音中同时出现双重音高感']],'关注的是发声现象，可能在持续发元音时特别容易听到。它不能简单等同于有意训练的泛音唱法，更不是“会说两种语言”。','audible diplophonia；episodes of diplophonia；assess diplophonia。','diphthong 是双元音，一个音节内元音音色发生滑动；diplophonia 是嗓音的双重音高现象。',('The recording revealed diplophonia during the sustained vowel.','录音显示，持续发元音时出现了双重嗓音。'),('The clinician noted intermittent diplophonia in the voice sample.','临床人员在嗓音样本中记录了间歇出现的双音现象。'),sources=['https://www.dictionary.com/browse/diplophonia','https://www.ncbi.nlm.nih.gov/medgen/536216']),
E('phonophobia','英 /ˌfəʊnəˈfəʊbiə/；美 /ˌfoʊnəˈfoʊbiə/','恐声；对声音的过度敏感或厌恶〔依语境〕','声音还没变得特别响，人已经很难承受或开始害怕它。','phono- “声音” + -phobia“恐惧、排斥”；医学使用不总等于严格精神科意义的恐惧症。',P+[['医学 phono- + -phobia → phonophobia','怕声音；一些语境也指对声音的敏感、厌恶']],'在偏头痛描述里可指声音难以忍受，不一定是“相信声音会伤害自己”的恐惧。理解文章时要看它采用哪种定义，别仅凭后缀把所有情况定成心理疾病。','phonophobia during a migraine；sound sensitivity；symptoms of phonophobia。','misophonia 常由特定声音模式触发强烈负面反应；phonophobia 的用法可涵盖害怕声音或声音敏感，边界依专业语境而定。',('The questionnaire asks about phonophobia during headache episodes.','问卷询问头痛发作时是否出现声音敏感。'),('The article defines phonophobia before comparing it with other forms of sound intolerance.','文章先定义恐声，再把它与其他声音耐受问题比较。'),sources=['https://www.dictionary.com/browse/phonophobia','https://en.wiktionary.org/wiki/phonophobia#English']),
E('phonation','英 /fəʊˈneɪʃən/；美 /foʊˈneɪʃən/','发声；喉部发声活动','呼出的气流经过喉部，声带等结构把它组织成嗓音。','借法语 phonation，以希腊 phōnḗ“声音”加 -ation 形成；英语 phonate 反而是后来从它逆构出的动词。',PA,'狭义常说声带振动产生嗓音，较广的语音研究也讨论喉部不同发声状态。它与口舌把声音塑成不同语音的 articulation 有关，却不是同一环节。','sustained phonation；phonation time；breathy phonation。','phonation 是发声过程；pronunciation 是一个词或音怎样读，范围和关注点不同。',('The exercise measures the duration of sustained phonation.','这项任务测量持续发声的时长。'),('The lecture distinguishes phonation from articulation.','讲座区分了喉部发声与构音。'),sources=['https://www.merriam-webster.com/dictionary/phonate','https://en.wiktionary.org/wiki/phonation#English']),
E('phonate','英 /ˈfəʊneɪt/；美 /ˈfoʊneɪt/','发声；发出嗓音〔专业用语〕','真正让发声系统工作，发出声音。','从 phonation 去掉看似名词词尾的部分逆构出 phonate；现代可对照 phon- + -ate，但历史方向是先名词、后动词。',PA+[['英语 phonation → phonate〔逆构〕','从发声过程的名称造出“发声”的动词']],'医学和语音实验中可要求一个人 phonate on a vowel，即持续发一个有声元音。日常一般直接说 make a sound、speak 或 say，而不会频繁使用这个技术动词。','phonate on a vowel；ask someone to phonate；phonate steadily。','articulate 常强调口舌如何形成清楚的音；phonate 强调发声，能发声不表示已经说出了可理解的词。',('The participant was asked to phonate on a steady vowel.','参与者被要求稳定地持续发一个元音。'),('The device recorded the signal while she phonated.','她发声时，设备记录了信号。'),sources=['https://www.merriam-webster.com/dictionary/phonate']),
E('hypophonesis','美 /ˌhaɪpoʊfəˈniːsɪs/；亦读 /ˌhaɪpoʊfoʊˈniːsɪs/','叩诊或听诊音减弱〔少见医学词〕','检查时本来能听到的声音，现在比通常弱。','hypo- “低于正常” + 声音成分 -phone + 过程名词形式 -sis；用于听诊、叩诊语境。',P+[['医学 hypo- + -phone + -sis → hypophonesis','检查中声音强度低于通常水平']],'这里不是简单指一个人说话轻。它描述检查所得的声音特征；单独这个词不说明究竟由哪种疾病造成，也不等于声音完全消失。','hypophonesis on examination；a note of hypophonesis。','hypophonia 通常指嗓音偏弱；hypophonesis 的词典义专门涉及听诊或叩诊，不能删几字母后当同一用法。',('The older report uses hypophonesis for the reduced intensity of the sound on auscultation.','这份较旧报告用 hypophonesis 表示听诊声音强度减弱。'),('The glossary explains hypophonesis without assigning it to a single cause.','术语表解释了听诊或叩诊音减弱，并未把它归结为单一病因。'),sources=['https://www.dictionary.com/browse/hypophonesis','https://www.collinsdictionary.com/dictionary/english/hypophonesis']),
E('ideophone','英 /ˈɪdiəfəʊn/；美 /ˈɪdiəfoʊn/','拟态词；以声音描摹感官印象的词','不只是告诉你发生了什么，还让你仿佛听见、看见或感到它的样子。','近代语言学 ideo- “观念、形象” + -phone“声音”；Doke 在二十世纪的研究推动了这个术语。',P+[['英语 ideo- + -phone → ideophone','通过语言的声音表现感官画面']],'它可以模仿声响，也可以表现动作、形状、触感等，所以范围不止“嘭、哗啦”式拟声词。各语言怎样把它们组成词类并不完全一致。','a vivid ideophone；ideophones of movement；use an ideophone。','idiophone 是体鸣乐器；ideophone 是语言表达。一个是乐器本体发声，一个是词的声音唤起感官印象。',('The storyteller used an ideophone to evoke a sudden, heavy movement.','讲故事的人用一个拟态词表现突然又沉重的动作。'),('The researchers asked speakers to explain the image conveyed by each ideophone.','研究者请说话者解释每个拟态词传达的感官画面。'),sources=['https://compass.onlinelibrary.wiley.com/doi/abs/10.1002/lnc3.361','https://en.wiktionary.org/wiki/ideophone#English']),
E('phonaesthesia','英 /ˌfəʊnɪsˈθiːziə/；美 /ˌfoʊnɪsˈθiːʒə/','语音联觉；声音与意义的联想联系','有些声音组合反复出现在意思相近的词里，耳朵就对它们形成了联想。','phon- “声音” + -aesthesia“感觉”，近代语言学术语；不是说所有声音都自带固定字典释义。',P+[['英语 phon- + -aesthesia → phonaesthesia','声音引起的意义或感官联想']],'例如 glow、glitter 等词中的 gl- 常让英语使用者想到光亮。但 glass、glad 等词不能因此随意硬拆成相同现代词根；联想规律与真实词源是两回事。','examples of phonaesthesia；study phonaesthesia；sound symbolism。','这里的“联觉”是语言学用法，不能仅凭这个词就等同于临床讨论的 synaesthesia。',('The seminar explored phonaesthesia in words associated with light.','研讨课讨论了与光有关的词中的语音联想。'),('Phonaesthesia can suggest a connection without proving a common etymology.','语音联想可以提示联系，却不能证明词源相同。'),sources=['https://dictionary.cambridge.org/pronunciation/english/phonaesthesia','https://en.wiktionary.org/wiki/phonaesthesia#English']),
E('phonaesthetics','英 /ˌfəʊnɪsˈθetɪks/；美 /ˌfoʊnɪsˈθetɪks/','语音美学；声音联想效果的研究','先不问句子说了什么，听它怎样流动，以及这些声音让人产生什么感觉。','phon- “声音” + aesthetics“美学、感受”，近代组合；不同作者也把声音象征和语音联想纳入其中。',P+[['英语 phon- + aesthetics → phonaesthetics','研究语言声音的听感、美感及相关联想']],'可讨论一个名字为什么显得柔和，诗句怎样通过音响产生气氛。判断受语言经验、个人偏好和语境影响，不能据此给所有语言排一张客观的美丑榜。','the phonaesthetics of a name；a discussion of phonaesthetics。','phonetics 研究发音及声音性质；phonaesthetics 进一步关注听感、联想与审美，不是测音高就能直接得出美感分数。',('The essay examines the phonaesthetics of invented place names.','文章分析了虚构地名的语音美感。'),('Their discussion of phonaesthetics included rhythm as well as individual sounds.','他们讨论语音美感时，既考虑单个声音，也考虑节奏。'),sources=['https://en.wiktionary.org/wiki/phonaesthetics#English','https://fonetica23.wordpress.com/wp-content/uploads/2017/09/a-dictionary-of-phonetics-and-phonology-trask-19961.pdf']),
E('phonestheme','英 /fəʊˈnesθiːm/；美 /foʊˈnesθiːm/；美亦 /ˈfoʊnəsθiːm/','音感素；有常见意义联想的声音片段','一个反复出现的小声音块，常把听者的联想往某一方向带。','Firth 在 1930 年提出的术语；Merriam-Webster 分析为 phoneme 与 esthetic 的混合形式，远接希腊“声音”和“感受”。',PM+[['英语 phoneme 与 esthetic 的混合 → phonestheme','把声音片段与常见意义联想联系起来的术语']],'gl- 在多个与光亮、视觉有关的词中出现，是常用示例。这种片段不必像普通词素那样能把整词拆成几个各自有意义的零件；也不是所有含它的词都符合联想。','the phonestheme gl-；identify a phonestheme；a recurrent phonestheme。','phoneme 区分词的声音单位；phonestheme 带有意义联想。不能把后者一概当成历史同源词根。',('The class discussed gl- as a phonestheme in glow and glitter.','课堂把 glow 和 glitter 中的 gl- 作为音感素来讨论。'),('Not every word beginning with the phonestheme shares the same association.','并非每个以这个音感素开头的词都有相同联想。'),sources=['https://www.merriam-webster.com/dictionary/phonestheme','https://www.cambridge.org/core/services/aop-cambridge-core/content/view/606C3C8EFA1AC73EDD5FC4AC3AFB5D5D/S1360674322000120a.pdf/the-coinages-in-seuss.pdf']),
E('phonesthemic','英 /ˌfəʊnesˈθiːmɪk/；美 /ˌfoʊnesˈθiːmɪk/','音感素的；涉及声音与意义片段联想的','不是整个词共享词根，而是一小段声音在多个词里带出相似感觉。','phonestheme + -ic，形容其联想模式或作用；主重音转到 -them-。',PM+[['英语 phonestheme + -ic → phonesthemic','与音感素或相应联想模式有关']],'phonesthemic pattern 可以说某个开头音群与一类意义常搭在一起。研究要看整个词群的分布与例外，不能从两个碰巧相似的词就断言存在规律。','phonesthemic patterns；a phonesthemic association；phonesthemic effects。','etymological 表示历史词源关系；phonesthemic 表示声音联想关系，两者有时相交，却不能互相替代。',('The study tests a phonesthemic association between a sound cluster and movement.','研究检验某个音群与运动意义之间的音感联想。'),('The author separates phonesthemic patterns from ordinary suffixes.','作者把音感模式与普通后缀区分开来。'),sources=['https://www.merriam-webster.com/dictionary/phonestheme','https://en.wiktionary.org/wiki/phonesthemic#English']),
E('phonosemantics','英 /ˌfəʊnəʊsɪˈmæntɪks/；美 /ˌfoʊnoʊsɪˈmæntɪks/〔按构词读音〕','语音语义关系研究；声音象征研究','研究声音的形状会不会让人倾向于想到某类意义，以及这种联系有多稳定。','phono- “声音” + semantics“语义学”，现代组合术语。',P+[['英语 phono- + semantics → phonosemantics','探讨语言声音与意义之间的联系']],'常讨论拟声、拟态、音感素等现象。它并不主张所有词都能仅凭读音猜出意思，更不能拿声音相像直接代替历史词源证据。','research in phonosemantics；an experiment in phonosemantics。','phonology 看声音怎样组成系统；phonosemantics 关注声音与意义是否发生联系。',('The experiment in phonosemantics asked listeners to match invented words with shapes.','这个语音语义实验请听者把自造词与形状配对。'),('The paper treats phonosemantics as a question to test, not a shortcut to every word’s origin.','论文把声音与意义的联系当作待检验的问题，而非解释所有词源的捷径。'),sources=['https://en.wiktionary.org/wiki/phonosemantics#English','https://www.mpi.nl/publications/item2286810/what-sound-symbolism-can-and-cannot-do-testing-iconicity-ideophones-five']),
E('logophonetic','英 /ˌlɒɡəʊfəˈnetɪk/；美 /ˌlɑːɡoʊfəˈnetɪk/〔按构词读音〕','语词与表音相结合的〔文字系统〕','一套文字既能用符号联系词或词素，也能用符号提示声音。','logo- 接希腊 lógos“词、言语” + phonetic“表音的”；是现代文字研究中的组合，不是古希腊已有的英语术语。',PH+[['并列构词材料：希腊 lógos → logo-','词、言语'],['英语 logo- + phonetic → logophonetic','语词符号与表音成分相结合']],'用于讨论古埃及等文字系统时，重点是词语意义与声音表示如何配合。并不是说每一个符号都必须同时完整表达一个词的全部意思和全部发音。','a logophonetic script；logophonetic writing；a logophonetic system。','logographic 强调语词或词素符号；phonetic 强调表音；logophonetic 说明系统中两类功能的结合，具体分类依研究者定义。',('The article describes the script as logophonetic because it combines word signs with sound signs.','文章把这套文字描述为语词与表音结合的系统，因为它同时使用语词符号和表音符号。'),('Understanding a logophonetic system requires more than treating every sign as a picture.','理解这种文字系统，不能只是把每个符号都当成一幅图画。'),sources=['https://benjamins.com/catalog/pc.21.3.05lan'])
])
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C1025');owned=set(m['owned_words'])
RROOT=[dict(id='C1025',meaning='声音；嗓音；语音',core='把空气中的声音，看成可传、可记、可组合的一条线',image='phone 把声音传远；phonograph 把声音记下；phonetics 细看怎样发声；symphony 把许多声音组织在一起。',intro='希腊 phōnḗ 的核心是声音、嗓音。英语既借来了古代的完整词，也在近现代用 phono-、-phone、-phony 创造技术与学术词。先判断是在谈传声设备、语言系统、音乐结构，还是人的发声状态，再读前半部分，意思会清楚很多。',forms='phon- 可扩成 phono-；-phone 常见于发声、收声设备及声音单位，-phony 常见于声音组织或状态，-phonic 常是相关形容词。phonetic、phoneme 各有借入历史；phonate 则从 phonation 逆构，不能一概按字面长短安排先后。',branches=[['传声与记录','phone、telephone、smartphone、headphone、earphone、microphone、megaphone、phonograph、phonogram、telephony、telephonic、stereo、stereophonic'],['语言声音的单位与规则','phonetic、phonetics、phonetically、phonics、phoneme、phonemic、allophone、homophone、homophonous、phonology、phonological、phonologist、phoneticist、phonotactics、morphophonology、archiphoneme、apophony、isophone'],['文字与声音联想','acrophony、acrophonic、logophonetic、ideophone、phonaesthesia、phonaesthetics、phonestheme、phonesthemic、phonosemantics'],['音乐的声音关系','symphony、symphonic、monophony、monophonic、homophony、homophonic、polyphony、polyphonic、heterophony、heterophonic、antiphon、antiphony、anthem、diaphony、idiophone、saxophone、xylophone'],['听感、发声与声音耐受','euphony、euphonic、euphonious、euphonize、cacophony、cacophonous、phonation、phonate、aphonia、aphonic、dysphonia、diplophonia、misophonia、phonophobia、hypophonesis']],contrasts='音素 phone 与音位 phoneme 分别看实际声音与语言中的区别作用。单声部、主调、复调在说旋律关系；单声道与立体声在说记录和重放，不能混算。ideophone 是词，idiophone 是乐器。声音联想 phonestheme 也不能替代真实同源证据。',practice='先解释：一群人齐唱可以是 monophonic，一架钢琴也能演奏 polyphonic 音乐；两者都可以录成 stereo。再用 pin / spin 里的 p 说明 phonetic 差别为何不一定是 phonemic 差别。',words=list(family),sources=['https://www.etymonline.com/word/phone','https://www.etymonline.com/word/phoneme','https://www.etymonline.com/word/phonetic','https://viva.pressbooks.pub/openmusictheory/chapter/texture/'])]
assert {w['word'] for w in W}==set(family)&owned, ((set(family)&owned)-{w['word'] for w in W},{w['word'] for w in W}-(set(family)&owned))
assert len({w['word'] for w in W})==len(W)
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa'],w['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history']),w['word']
for k,d in [('roots',RROOT),('words',W)]: (OUT/f'{k}_batch200_spec_26_phon.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
print('C1025',len(W),'new',len(RROOT[0]['words']),'references',sum(len(w['examples']) for w in W),'examples')
